namespace BobbyBoi;
record FishingCatch(string Name,int Weight,string Quip);
static class WorldLoot {
 public static readonly FishingCatch[] Fishing=[new("Raw Cod",17,"fish acquired"),new("Raw Salmon",13,"sushi?"),new("Stick",12,"excellent rod upgrade"),new("Dirt",10,"ocean dirt"),new("Rotten Flesh",8,"expired sushi"),new("Old Boot",8,"size 64"),new("Bowl",6,"soup without soup"),new("String",6,"i caught my own line"),new("Name Tag",4,"who are you"),new("Enchanted Book",4,"how to read"),new("Saddle",3,"where horse"),new("Golden Apple",3,"expensive lunch"),new("Emerald",3,"rent money"),new("Diamond",2,"retirement fund"),new("Diamond Sword",1,"sharp fish"),new("Treasure Chest",1,"loot goblin"),new("Enchanted Fishing Rod",1,"rod caught a rod"),new("Windows Error",2,"the ocean crashed"),new("Tiny Steve",2,"wrong server"),new("Unpaid Electricity Bill",2,"the villagers found me"),new("Crafting Table",2,"heavy breakfast"),new("Suspiciously Large Fish",2,"the fish caught me"),new("Paper: you caught nothing",2,"the receipt says nothing"),new("Fish with a Rod",1,"he was fishing for me"),new("Picture of BobbyBoi Fishing",1,"who took this"),new("Mini BobbyBoi",1,"identity crisis"),new("Paper: skill issue",2,"personal attack")];
 public static FishingCatch Catch(Random rng){int roll=rng.Next(Fishing.Sum(x=>x.Weight));foreach(var c in Fishing){roll-=c.Weight;if(roll<0)return c;}return Fishing[0];}
 public static (string Kind,Dictionary<string,int> Items,bool Nested) Chest(Random rng){int roll=rng.Next(100);if(roll<10)return("Chest inside a chest",new(){{"Dirt",1}},true);if(roll<30)return("Rare chest",new(){{rng.Next(2)==0?"Diamond":"Emerald",rng.Next(1,4)},{"Enchanted Book",1}},false);if(roll<48){var jokes=new[]{"Suspicious Potato","Diamond: definitely real","Stick worth 900 emeralds","Minecraft Divorce Certificate","Book: How To Read","Map to Nowhere","Fish named CEO","Bucket of Disappointment","Million Emerald Check","Paper: unemployment"};return("Cursed chest",new(){{jokes[rng.Next(jokes.Length)],1}},false);}return("Common chest",new(){{new[]{"Dirt","Bread","Cobblestone","Bone","Stick","Apple"}[rng.Next(6)],rng.Next(1,roll>90?65:5)}},false);}
}
